-- MeshLibrary (SKETCH for Phase 6 "Blender models only"; would live in src/shared/MeshLibrary.lua)
--
-- One place that turns the Model asset ids of the Blender uploads (shared/MeshIds.lua, generated by
-- tools/upload_assets.py) into ready-to-clone templates, and falls back to today's Part builders whenever a model is
-- not there (no id yet, still loading, LoadAsset failed, moderation pending, a client could not fetch the mesh).
--
--   SERVER  MeshLibrary.Start()          loads every id in the background (AssetService:LoadAssetAsync, falling back to
--                                        InsertService:LoadAsset; both are server-only for us), normalises each result
--                                        and parents the template to ReplicatedStorage.MeshLibrary.<Key> (status in the
--                                        attribute ML_Status: "loading" | "ready" | "failed").
--   CLIENT  MeshLibrary.Start()          watches that folder (templates replicate like any instance), preloads the mesh
--                                        data (ContentProvider:PreloadAsync) and marks a template unusable on THIS
--                                        client when a fetch fails.
--   BOTH    MeshLibrary.Clone(key, opts) -> Model | nil      synchronous; nil = "use the Part build"
--           MeshLibrary.Build(key, opts, fallback, ...) -> Model, "mesh" | "parts"
--           MeshLibrary.IsReady(key) -> bool
--           MeshLibrary.OnReady(key, fn)  fn(key) once the template is usable here (at once when it already is)
--           MeshLibrary.Tag(target, key, keep)   SERVER: marks a Part build (lobby / home / arena / dungeon piece built
--                                        at boot) to be dressed with mesh `key` on every client that has it
--           MeshLibrary.Dress(target, key, opts)  CLIENT: keeps the Part build as the invisible collider (locally) and
--                                        shows the mesh on it once ready; clients whose mesh fetch failed keep the Parts
--           MeshLibrary.Tint(model, colors)  MeshPart.Color by part name (vertex colours multiply with Color)
--
-- Plain Lua 5.1 syntax (tools/check.mjs); numbers only, no "rbxassetid://" literals (check.mjs asset-id rule).
-- Docs behind each choice: research REPORT.md (InsertService:LoadAsset ownership rule, AssetService:LoadAssetAsync,
-- MeshPart.MeshId not scriptable, CollisionFidelity not scriptable at runtime, RenderFidelity NotReplicated,
-- SurfaceAppearance maps PluginSecurity, vertex colour x Color, importer defaults: Anchored off, *_Att -> Attachment).

local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local MeshLibrary = {}

local FOLDER_NAME = "MeshLibrary"
local DRESS_TAG = "ML_Dress"
local MAX_PARALLEL = 4 -- concurrent LoadAsset calls on the server
local RETRY_DELAYS = { 2, 5, 12 } -- seconds between attempts
local SLOW_SECONDS = 20 -- a load slower than this is logged (the call itself cannot be cancelled)
local WHITE = Color3.fromRGB(255, 255, 255)

-- Per-key options (would come from a shared MeshSpecs table written next to blender/meshes.json):
--   Collide = false        the mesh is visual only (default); the Part build or a collider part does physics
--   ExpectedSize = Vector3  studs; a 100x / 0.01x mismatch (FBX unit mistake) is corrected with Model:ScaleTo
--   Tint = { PartName = Color3 }   colours applied to the template (white vertex colours x Color)
--   Material = Enum.Material.X     default SmoothPlastic for the cartoon look
MeshLibrary.Specs = {}

local ids = {} -- key -> asset id (number)
local status = {} -- key -> "missing" | "loading" | "ready" | "failed" (this side)
local localBroken = {} -- client: key -> true when the mesh data could not be fetched on this device
local localReady = {} -- client: key -> true once PreloadAsync fetched the mesh data on this device
local IS_SERVER = RunService:IsServer()
local waiters = {} -- key -> { fn, ... }
local folder = nil
local started = false

local function log(msg)
	print("[MeshLibrary] " .. msg)
end

local function readIds()
	local shared = script.Parent
	local mod = shared and shared:FindFirstChild("MeshIds")
	if not mod then
		return {}
	end
	local ok, t = pcall(require, mod)
	if not ok or type(t) ~= "table" then
		warn("[MeshLibrary] MeshIds did not load: " .. tostring(t))
		return {}
	end
	local out = {}
	for key, id in pairs(t) do
		local n = tonumber(id)
		if type(key) == "string" and n and n > 0 then
			out[key] = math.floor(n)
		end
	end
	return out
end

local function notify(key)
	local list = waiters[key]
	waiters[key] = nil
	if list then
		for _, fn in ipairs(list) do
			task.spawn(fn, key)
		end
	end
end

local function templateOf(key)
	if not folder then
		folder = ReplicatedStorage:FindFirstChild(FOLDER_NAME)
	end
	local tpl = folder and folder:FindFirstChild(key)
	if tpl and tpl:GetAttribute("ML_Status") == "ready" then
		return tpl
	end
	return nil
end

-- usable HERE: on the server the template exists; on a client its mesh data was also downloaded (a clone made
-- before that would render invisible until the fetch ends, or forever when it fails)
local function usable(key)
	if localBroken[key] or not templateOf(key) then
		return false
	end
	return IS_SERVER or localReady[key] == true
end

function MeshLibrary.IsReady(key)
	return usable(key)
end

function MeshLibrary.Status(key)
	if localBroken[key] then
		return "failed"
	end
	if usable(key) then
		return "ready"
	end
	if templateOf(key) then
		return "loading" -- client: replicated, still downloading the mesh data
	end
	return status[key] or (ids[key] and "loading" or "missing")
end

function MeshLibrary.OnReady(key, fn)
	if MeshLibrary.IsReady(key) then
		task.spawn(fn, key)
		return
	end
	waiters[key] = waiters[key] or {}
	table.insert(waiters[key], fn)
end

----------------------------------------------------------------------
-- Server: load + normalise
----------------------------------------------------------------------
-- LoadAsset returns a Model that WRAPS the asset; a Model upload of an FBX is (docs) "a Model container containing
-- one or more MeshPart objects", stored as a package (PackageLink child). Unwrap one level when the wrapper holds a
-- single Model.
local function unwrap(container)
	local kids = container:GetChildren()
	if #kids == 1 and kids[1]:IsA("Model") then
		local inner = kids[1]
		inner.Parent = nil
		container:Destroy()
		return inner
	end
	return container
end

local function largestPart(model)
	local best, bestVol = nil, -1
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("BasePart") then
			local v = d.Size.X * d.Size.Y * d.Size.Z
			if v > bestVol then
				best, bestVol = d, v
			end
		end
	end
	return best
end

local function normalise(key, model, assetId)
	local spec = MeshLibrary.Specs[key] or {}
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("PackageLink") or d:IsA("Script") or d:IsA("LocalScript") or d:IsA("ModuleScript") then
			d:Destroy() -- a package link is Studio-only metadata; scripts would never belong in a mesh upload
		end
	end
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("BasePart") then
			d.Anchored = true -- the importer default is NOT anchored: an unanchored template would fall when used
			local collide = spec.Collide == true
			d.CanCollide = collide
			d.CanTouch = collide
			d.CanQuery = collide
			d.Massless = true
			if d:IsA("MeshPart") then
				-- vertex colours are MULTIPLIED by MeshPart.Color; the default grey (163,162,165) darkens them
				d.Color = (spec.Tint and spec.Tint[d.Name]) or WHITE
				d.Material = spec.Material or Enum.Material.SmoothPlastic
			end
		end
	end
	model.Name = key
	model.PrimaryPart = model:FindFirstChild("Root", true) or model:FindFirstChild("Body", true) or largestPart(model)
	-- a "Pivot_Att" empty in Blender becomes an Attachment: the model's pivot (pet feet, prop base, ...)
	local pivot = model:FindFirstChild("Pivot_Att", true)
	if pivot and pivot:IsA("Attachment") then
		model.WorldPivot = pivot.WorldCFrame
	end
	-- FBX unit mistakes show up as 100x / 0.01x: correct them and say so
	if typeof(spec.ExpectedSize) == "Vector3" then
		local got = model:GetExtentsSize()
		local ratio = spec.ExpectedSize.Magnitude / math.max(got.Magnitude, 1e-6)
		if ratio > 20 or ratio < 0.05 then
			local ok = pcall(function()
				model:ScaleTo(model:GetScale() * ratio)
			end)
			warn(string.format("[MeshLibrary] %s (asset %d) is %.3gx its expected size; rescaled=%s - fix the FBX export scale",
				key, assetId, 1 / ratio, tostring(ok)))
		end
	end
	model:SetAttribute("ML_Key", key)
	model:SetAttribute("ML_AssetId", assetId)
	return model
end

local function permanentError(msg)
	msg = string.lower(tostring(msg))
	return string.find(msg, "not authorized", 1, true) or string.find(msg, "does not exist", 1, true)
		or string.find(msg, "invalid", 1, true)
end

local function loadOnce(assetId)
	local AssetService = game:GetService("AssetService")
	local ok, res = pcall(function()
		return AssetService:LoadAssetAsync(assetId)
	end)
	if ok and res then
		return true, res
	end
	local firstErr = res
	local InsertService = game:GetService("InsertService")
	ok, res = pcall(function()
		return InsertService:LoadAsset(assetId)
	end)
	if ok and res then
		return true, res
	end
	return false, tostring(firstErr) .. " | " .. tostring(res)
end

local running = 0

local function loadKey(key, assetId)
	local holder = folder:FindFirstChild(key)
	if not holder then
		holder = Instance.new("Model")
		holder.Name = key
		holder:SetAttribute("ML_Status", "loading")
		holder.Parent = folder
	end
	status[key] = "loading"
	while running >= MAX_PARALLEL do
		task.wait(0.1)
	end
	running = running + 1
	local lastErr = nil
	for attempt = 1, #RETRY_DELAYS + 1 do
		local t0 = os.clock()
		local ok, res = loadOnce(assetId)
		local dt = os.clock() - t0
		if dt > SLOW_SECONDS then
			log(string.format("%s took %.1f s to load", key, dt))
		end
		if ok then
			local okNorm, model = pcall(normalise, key, unwrap(res), assetId)
			if okNorm and model and model.PrimaryPart then
				model:SetAttribute("ML_Status", "ready")
				model:SetAttribute("ML_LoadMs", math.floor(dt * 1000 + 0.5))
				holder:Destroy()
				model.Parent = folder -- replicates to every client
				status[key] = "ready"
				running = running - 1
				log(string.format("%s ready (asset %d, %d ms)", key, assetId, math.floor(dt * 1000 + 0.5)))
				notify(key)
				return
			end
			lastErr = okNorm and "the asset holds no parts" or tostring(model)
			if okNorm and model then
				model:Destroy()
			end
		else
			lastErr = res
		end
		if permanentError(lastErr) or attempt > #RETRY_DELAYS then
			break
		end
		task.wait(RETRY_DELAYS[attempt])
	end
	running = running - 1
	status[key] = "failed"
	holder:SetAttribute("ML_Status", "failed")
	holder:SetAttribute("ML_Error", string.sub(tostring(lastErr), 1, 200))
	warn(string.format("[MeshLibrary] %s (asset %d) failed, the Part build stays: %s", key, assetId, tostring(lastErr)))
end

----------------------------------------------------------------------
-- Client: preload + per-device failure
----------------------------------------------------------------------
local function preload(tpl)
	local key = tpl.Name
	local ContentProvider = game:GetService("ContentProvider")
	local failed = false
	local ok, err = pcall(function()
		ContentProvider:PreloadAsync({ tpl }, function(_, fetchStatus)
			if fetchStatus == Enum.AssetFetchStatus.Failure then
				failed = true
			end
		end)
	end)
	if not ok then
		log("PreloadAsync unavailable for " .. key .. ": " .. tostring(err))
	end
	if failed then
		localBroken[key] = true -- this device could not fetch the mesh: keep using the Part build here
		warn("[MeshLibrary] " .. key .. " mesh data failed to download on this client; using the Part build")
		return
	end
	localReady[key] = true
	notify(key)
end

local function watchTemplate(tpl)
	if tpl:GetAttribute("ML_Status") == "ready" then
		task.spawn(preload, tpl)
	end
end

----------------------------------------------------------------------
-- Public
----------------------------------------------------------------------
function MeshLibrary.Start()
	if started then
		return
	end
	started = true
	ids = readIds()
	if IS_SERVER then
		folder = ReplicatedStorage:FindFirstChild(FOLDER_NAME)
		if not folder then
			folder = Instance.new("Folder")
			folder.Name = FOLDER_NAME
			folder.Parent = ReplicatedStorage
		end
		local n = 0
		for key, assetId in pairs(ids) do
			n = n + 1
			task.spawn(loadKey, key, assetId)
		end
		log(n .. " mesh model(s) to load")
	else
		task.spawn(function()
			folder = ReplicatedStorage:WaitForChild(FOLDER_NAME, 60)
			if not folder then
				return
			end
			for _, tpl in ipairs(folder:GetChildren()) do
				watchTemplate(tpl)
			end
			folder.ChildAdded:Connect(watchTemplate)
		end)
		local function dressTagged(target)
			local key = target:GetAttribute("ML_DressKey")
			if type(key) == "string" then
				local keep = {}
				for name in string.gmatch(target:GetAttribute("ML_Keep") or "", "[^,]+") do
					keep[name] = true
				end
				MeshLibrary.Dress(target, key, { Keep = keep })
			end
		end
		for _, target in ipairs(CollectionService:GetTagged(DRESS_TAG)) do
			dressTagged(target)
		end
		CollectionService:GetInstanceAddedSignal(DRESS_TAG):Connect(dressTagged)
	end
end

-- A fresh copy of the template, or nil (caller builds Parts). opts: Scale (number), Tint ({ name = Color3 }),
-- RenderFidelity (client: Enum.RenderFidelity.Performance on low graphics; the property does not replicate).
function MeshLibrary.Clone(key, opts)
	if not usable(key) then
		return nil
	end
	local tpl = templateOf(key)
	local model = tpl:Clone()
	opts = type(opts) == "table" and opts or {}
	local scale = tonumber(opts.Scale)
	if scale and scale > 0 and math.abs(scale - 1) > 1e-3 then
		local ok = pcall(function()
			model:ScaleTo(model:GetScale() * scale)
		end)
		if not ok then
			model:Destroy()
			return nil
		end
	end
	if type(opts.Tint) == "table" then
		MeshLibrary.Tint(model, opts.Tint)
	end
	if opts.RenderFidelity then
		for _, d in ipairs(model:GetDescendants()) do
			if d:IsA("MeshPart") then
				pcall(function()
					d.RenderFidelity = opts.RenderFidelity
				end)
			end
		end
	end
	model:SetAttribute("ML_Mesh", true)
	return model
end

function MeshLibrary.Build(key, opts, fallback, ...)
	local model = MeshLibrary.Clone(key, opts)
	if model then
		return model, "mesh"
	end
	return fallback(...), "parts"
end

-- colors: { PartName = Color3 } (exact name) - same names the Part builders recolour today (Body, EyeIris, ...)
function MeshLibrary.Tint(model, colors)
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("MeshPart") then
			local c = colors[d.Name]
			if typeof(c) == "Color3" then
				d.Color = c
			end
		end
	end
end

-- SERVER side of dressing: the Part build stays the real (replicated, colliding, test-visible) model; every client
-- that has the mesh hides the Parts locally and shows the mesh. keep: { "SignBoard", ... } parts that stay visible.
function MeshLibrary.Tag(target, key, keep)
	target:SetAttribute("ML_DressKey", key)
	if type(keep) == "table" then
		target:SetAttribute("ML_Keep", table.concat(keep, ","))
	end
	CollectionService:AddTag(target, DRESS_TAG)
end

-- CLIENT: keep `target` (a Part build: anchored, colliding, named parts the tests know) as the invisible collider and show
-- the mesh on top of it once ready. Parts named in opts.Keep (signs, prompts, SurfaceGui hosts) stay visible.
function MeshLibrary.Dress(target, key, opts)
	opts = type(opts) == "table" and opts or {}
	if target:FindFirstChild("ML_Mesh") then
		return
	end
	MeshLibrary.OnReady(key, function()
		if not target.Parent or target:FindFirstChild("ML_Mesh") then
			return
		end
		local mesh = MeshLibrary.Clone(key, opts)
		if not mesh then
			return
		end
		mesh.Name = "ML_Mesh"
		mesh:PivotTo(target:GetPivot() * (opts.Offset or CFrame.new()))
		local keep = opts.Keep or {}
		for _, d in ipairs(target:GetDescendants()) do
			if d:IsA("BasePart") and not keep[d.Name] then
				d.Transparency = 1 -- set on the client: local only (no replication); still collides, still found by name
				for _, deco in ipairs(d:GetChildren()) do
					if deco:IsA("Decal") or deco:IsA("Texture") then
						deco.Transparency = 1
					end
				end
			end
		end
		mesh.Parent = target
	end)
end

return MeshLibrary
